import math
import re
from datetime import datetime, date, timedelta
from decimal import Decimal, ROUND_FLOOR, ROUND_CEILING
import openpyxl

SRC='/root/Inventory_and_Shipments_Latest.xlsx'
OUT='/root/additional_shipments_needed_updated_july_2025.xlsx'


def as_date(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, str):
        s=v.strip()
        if not s:
            return None
        for fmt in ('%Y-%m-%d','%m/%d/%Y','%Y/%m/%d','%m/%d/%y'):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                continue
        raise ValueError(f'Unrecognized date string: {v!r}')
    raise TypeError(f'Unsupported date type: {type(v)} ({v!r})')


def iso_or_blank(d):
    return d.isoformat() if isinstance(d, date) else None


def norm(s):
    return re.sub(r'\s+',' ', str(s).strip().lower())


def dec(x):
    """Decimal from int/float/str without binary float artifacts."""
    if x is None:
        return Decimal('0')
    if isinstance(x, Decimal):
        return x
    if isinstance(x, (int,)):
        return Decimal(x)
    if isinstance(x, float):
        return Decimal(str(x))
    if isinstance(x, str):
        return Decimal(x.strip())
    return Decimal(str(x))


