    nonempty=[x for x in row if x is not None and not (isinstance(x,str) and x.strip()=='')]
    str_count=sum(isinstance(x,str) and x.strip()!='' for x in nonempty)
    if len(nonempty)>=3 and str_count>=3:
        header_row=r
        break
if header_row is None:
    raise RuntimeError('Could not detect Current Inventory header row')

