        col_sku=idx
    elif 'in stock' in nh and 'case' in nh:
        col_cases=idx
    elif 'rate of sale' in nh and 'case' in nh:
        col_rate=idx

if not (col_sku and col_cases and col_rate):
    raise RuntimeError(f'Current Inventory mapping failed sku={col_sku} cases={col_cases} rate={col_rate}')

inventory_rows=[]
