        continue
    sku=str(sku).strip()
    current_cases=ws.cell(r,col_cases).value
    daily_rate=ws.cell(r,col_rate).value
    inventory_rows.append({
        'Product_SKU': sku,
        'Current_Cases': dec(current_cases),
        'Daily_Rate': dec(daily_rate),
    })

